import json
import re
import sys
statusCode, lookupStatus, message = 502, "invalid-response", "Organization response is invalid"
organizationMoid, organizationJson = "", "{}"
inspectionComplete = False
try:
    payload = json.loads(sys.argv[1])
    if not isinstance(payload, dict): raise ValueError("Organization response must be an object")
    count, rows = payload.get("Count"), payload.get("Results")
    if isinstance(count, bool) or not isinstance(count, int) or count < 0: raise ValueError("Count must be a nonnegative integer")
    if not isinstance(rows, list): raise ValueError("Results must be an array")
    if count != len(rows): raise ValueError("Count and Results length differ; the bounded page is incomplete")
    if count > 2: raise ValueError("Count exceeds the two-row lookup bound")
    if count == 0: statusCode, lookupStatus, message = 404, "not-found", "No organization matched the exact requested name"
    elif count != 1: statusCode, lookupStatus, message = 409, "ambiguous", "More than one organization matched the exact requested name"
    else:
        item = rows[0]
        if not isinstance(item, dict) or item.get("Name") != sys.argv[2]: raise ValueError("Organization Name does not match exactly")
        if item.get("ObjectType") != "organization.Organization" or item.get("ClassId") != "organization.Organization": raise ValueError("Organization discriminators do not match")
        moid = item.get("Moid")
        pattern = r"[0-9a-fA-F]{24}" if sys.argv[3] == "Hex24" else r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}"
        if not isinstance(moid, str) or re.fullmatch(pattern, moid) is None: raise ValueError("Organization Moid is missing or malformed")
        organizationMoid = moid
        projected = {key:item[key] for key in ("Moid", "Name", "ObjectType", "ClassId")}
        organizationJson = json.dumps(projected, separators=(",", ":"))
        resultJson = json.dumps({"Count":1,"Results":[projected]}, separators=(",", ":"))
        statusCode, lookupStatus, message = 200, "exact", "Organization resolved exactly"
    inspectionComplete = True
except Exception as exc:
    statusCode, lookupStatus, message, inspectionComplete = 502, "invalid-response", str(exc), True
errorMessage = "" if statusCode == 200 else message
if statusCode != 200: resultJson = json.dumps({"status":lookupStatus,"error":message}, separators=(",", ":"))

import json
import re
import sys

selector = sys.argv[2]
organizationName = sys.argv[3]
organizationMoid = sys.argv[4]
expectedMoid = sys.argv[5]
expectedType = sys.argv[6]
crossCheckRequested = bool(expectedMoid and expectedType)
serverStatus = "invalid-response"
statusCode = "502"
statusMessage = "Server lookup response was invalid"
errorMessage = ""
resultJson = "{}"
resolvedServerMoid = ""
resolvedServerObjectType = ""

def safe_moid(value):
    return isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}", value) is not None

def exact_text(value, maximum):
    return isinstance(value, str) and bool(value) and value == value.strip() and len(value) <= maximum and not any(ord(ch) < 32 for ch in value)

def valid_permission(rel):
    if not isinstance(rel, dict) or not safe_moid(rel.get("Moid")):
        return False
    objectType = rel.get("ObjectType")
    if objectType is None:
        return rel.get("Moid") == organizationMoid and rel.get("ClassId") in (None, "mo.MoRef")
    if not isinstance(objectType, str) or not objectType.strip() or objectType != objectType.strip():
        return False
    return rel.get("ClassId") in (None, "mo.MoRef", objectType)

identity = {
    "Name": None,
    "Serial": None,
    "Model": None,
    "Moid": None,
    "ObjectType": None,
    "organization": {
        "Name": organizationName,
        "Moid": organizationMoid,
        "ObjectType": "organization.Organization"
    }
}

try:
    payload = json.loads(sys.argv[1])
    if not isinstance(payload, dict):
        raise ValueError("PhysicalSummary response must be a JSON object.")
    count = payload.get("Count")
    values = payload.get("Results")
    if isinstance(count, bool) or not isinstance(count, int) or count < 0:
        raise ValueError("PhysicalSummary response Count must be a non-negative integer.")
    if not isinstance(values, list):
        raise ValueError("PhysicalSummary response is missing a Results array.")
    if count > 2:
        raise ValueError("PhysicalSummary response Count exceeds the bounded two-result page, so the exact result set is truncated.")
    if count != len(values):
        raise ValueError("PhysicalSummary response Count does not equal the returned Results length; the bounded page is incomplete.")
    if count == 0:
        serverStatus = "not-found"
        statusCode = "404"
        statusMessage = "Physical server was not found"
        errorMessage = "No exact organization-scoped PhysicalSummary matched Server Name or Serial."
    elif count > 1:
        serverStatus = "ambiguous"
        statusCode = "409"
        statusMessage = "Physical server lookup was ambiguous"
        errorMessage = "Multiple organization-scoped PhysicalSummaries matched Server Name or Serial."
    else:
        item = values[0]
        problems = []
        if not isinstance(item, dict):
            problems.append("PhysicalSummary result is not an object.")
        else:
            name = item.get("Name")
            serial = item.get("Serial")
            model = item.get("Model")
            moid = item.get("Moid")
            sourceType = item.get("SourceObjectType")
            permissions = item.get("PermissionResources")
            identity.update({"Name": name, "Serial": serial, "Model": model, "Moid": moid, "ObjectType": sourceType})
            if not exact_text(name, 128):
                problems.append("PhysicalSummary Name must be a non-empty exact string without surrounding whitespace or controls.")
            if not exact_text(serial, 128):
                problems.append("PhysicalSummary Serial must be a non-empty exact string without surrounding whitespace or controls.")
            if name != selector and serial != selector:
                problems.append("PhysicalSummary matches neither the exact Name nor exact Serial selector.")
            if not exact_text(model, 256):
                problems.append("PhysicalSummary Model must be a non-empty exact string without surrounding whitespace or controls.")
            if not safe_moid(moid):
                problems.append("PhysicalSummary Moid is missing or not URL-safe.")
            if item.get("ObjectType") != "compute.PhysicalSummary" or item.get("ClassId") != "compute.PhysicalSummary":
                problems.append("PhysicalSummary discriminators are invalid.")
            if sourceType not in ("compute.Blade", "compute.RackUnit"):
                problems.append("PhysicalSummary SourceObjectType must be compute.Blade or compute.RackUnit.")
            if not isinstance(permissions, list) or not permissions:
                problems.append("PhysicalSummary PermissionResources must be a non-empty array.")
            elif not all(valid_permission(rel) for rel in permissions):
                problems.append("PhysicalSummary contains an invalid PermissionResources relationship.")
            else:
                matches = [rel for rel in permissions if rel.get("Moid") == organizationMoid and rel.get("ObjectType") in (None, "organization.Organization")]
                if len(matches) != 1:
                    problems.append("PhysicalSummary must contain exactly one matching organization permission relationship.")
        if problems:
            serverStatus = "invalid-response"
            statusCode = "502"
            statusMessage = "Server lookup response was invalid"
            errorMessage = " ".join(problems)
        elif crossCheckRequested and (identity["Moid"] != expectedMoid or identity["ObjectType"] != expectedType):
            serverStatus = "identity-mismatch"
            statusCode = "409"
            statusMessage = "Resolved server does not match expected identity"
            errorMessage = "The Name-or-Serial selector resolved a different server Moid or concrete ObjectType. No mutation is safe."
        else:
            serverStatus = "exact"
            statusCode = "200"
            statusMessage = "Physical server identity resolved"
            errorMessage = ""
            resolvedServerMoid = identity["Moid"]
            resolvedServerObjectType = identity["ObjectType"]
    resultJson = json.dumps({
        "status": serverStatus,
        "message": errorMessage or statusMessage,
        "selector": selector,
        "crossCheckPerformed": crossCheckRequested,
        "expected": {"Moid": expectedMoid, "ObjectType": expectedType} if crossCheckRequested else None,
        "server": identity
    }, separators=(",", ":"))
except Exception as exc:
    serverStatus = "invalid-response"
    statusCode = "502"
    statusMessage = "Server lookup response was invalid"
    errorMessage = str(exc)
    resultJson = json.dumps({
        "status": serverStatus,
        "error": errorMessage,
        "selector": selector,
        "crossCheckPerformed": crossCheckRequested,
        "expected": {"Moid": expectedMoid, "ObjectType": expectedType} if crossCheckRequested else None,
        "server": identity
    }, separators=(",", ":"))

helperReady = serverStatus in ("not-found", "ambiguous", "invalid-response", "identity-mismatch", "exact") and bool(statusCode and statusMessage and resultJson) and (serverStatus != "exact" or all((resolvedServerMoid, resolvedServerObjectType)))
